import { useState, useRef, useEffect } from 'react'
import { MobileFormDrawer } from '@/components/ui/mobile-form-drawer'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Textarea } from '@/components/ui/textarea'
import { SimpleSelect } from '@/components/ui/select'
import { ChevronDown, ChevronUp } from 'lucide-react'
import type { GearItem, WeightUnit } from '@/types/database'
import { GEAR_CATEGORIES } from '@/constants/gear'
import { convertToGrams, parseWeightInput, formatWeightWithUnit } from '@/utils/weight'
import { ImageUploadField } from './ImageUploadField'

interface EditGearFormProps {
  item: GearItem
  onUpdate: (id: string, updates: Partial<Omit<GearItem, 'id' | 'user_id' | 'created_at' | 'updated_at'>>) => void
  onCancel: () => void
}

export function EditGearForm({ item, onUpdate, onCancel }: EditGearFormProps) {
  const [loading, setLoading] = useState(false)
  const [formData, setFormData] = useState({
    name: item.name,
    brand: item.brand || '',
    model: item.model || item.description || '',
    category: item.category,
    quantity: item.quantity,
    worn: item.worn,
    consumable: item.consumable,
    price: item.price || '',
    notes: item.notes || '',
    description: item.description || '',
    image_url: item.image_url || '',
  })

  const [weightValue, setWeightValue] = useState(() => {
    return item.weight_grams.toString()
  })
