        setBrand('')
        setModel('')
        setWeightValue('')
        setCategory('Other')
        setQuantity(1)
        setWorn(false)
        setConsumable(false)
        setPrice('')
        setDescription('')
        setImageUrl('')
        setNotes('')
        setShowAdvanced(false)

        // Re-focus for quick entry
        nameInputRef.current?.focus()
      }

