      captureError(error as Error, {
        component: 'GearForm',
        action: 'handleSubmit',
        isEditing,
        formData: { 
          name, 
          brand, 
          weightValue, 
          weightUnit, 
          category, 
          quantity, 
          worn, 
          consumable, 
          price, 
          description, 
          imageUrl, 
          notes 
        }
      })
    } finally {
      setLoading(false)
    }
  }

  const handleKeyDown = (e: React.KeyboardEvent) => {
    // Cmd/Ctrl + Enter to submit
    if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) {
      handleSubmit(e)
    }
  }

