import { useState } from 'react'
import { GearForm } from '@/components/gear/GearForm'
import { Button } from '@/components/ui/button'
import { Card } from '@/components/ui/card'
import type { GearItem } from '@/types/database'

// Mock gear item for testing edit mode
const mockGearItem: Partial<GearItem> = {
  name: 'Test Backpack',
  brand: 'Test Brand',
  model: 'Test Model',
  category: 'Backpacks',
  weight_grams: 1500,
  quantity: 1,
  worn: false,
  consumable: false,
  price: 299.99,
  description: 'A test backpack for form testing',
  notes: 'These are test notes',
  image_url: 'https://example.com/test-image.jpg'
}

export function TestForms() {
  const [mode, setMode] = useState<'add' | 'edit' | 'simplified' | 'non-standalone'>('add')

  const handleSubmit = (data: any) => {
    console.log('Form submitted:', data)
    alert(`Form submitted successfully! Check console for data.`)
  }

  return (
    <div className="min-h-screen bg-background p-4">
      <div className="max-w-4xl mx-auto space-y-6">
        <div className="text-center">
          <h1 className="text-2xl font-bold mb-4">GearForm Test Page</h1>
          <p className="text-muted-foreground mb-6">
            This page allows testing different variations of the GearForm component
          </p>
        </div>

        {/* Mode Selector */}
        <Card className="p-4">
          <h2 className="text-lg font-semibold mb-3">Test Mode</h2>
          <div className="flex flex-wrap gap-2">
            <Button
              variant={mode === 'add' ? 'default' : 'outline'}
              onClick={() => setMode('add')}
            >
              Add Mode
            </Button>
            <Button
              variant={mode === 'edit' ? 'default' : 'outline'}
              onClick={() => setMode('edit')}
            >
              Edit Mode
            </Button>
            <Button
              variant={mode === 'simplified' ? 'default' : 'outline'}
              onClick={() => setMode('simplified')}
            >
              Simplified Mode
            </Button>
            <Button
              variant={mode === 'non-standalone' ? 'default' : 'outline'}
              onClick={() => setMode('non-standalone')}
            >
              Non-Standalone
            </Button>
          </div>
        </Card>

        {/* Form Container */}
        <div className="space-y-4">
          <h2 className="text-lg font-semibold">
            Form Preview - {mode.charAt(0).toUpperCase() + mode.slice(1)} Mode
          </h2>

          {mode === 'add' && (
            <GearForm
              isEditing={false}
              onSubmit={handleSubmit}
              simplified={false}
              standalone={true}
            />
          )}

          {mode === 'edit' && (
            <GearForm
              isEditing={true}
              initialData={mockGearItem}
              onSubmit={handleSubmit}
              simplified={false}
              standalone={true}
            />
          )}

          {mode === 'simplified' && (
            <div className="space-y-4">
              <Card className="p-4">
                <h3 className="font-medium mb-2">Simplified Add Mode</h3>
                <GearForm
                  isEditing={false}
                  onSubmit={handleSubmit}
                  simplified={true}
                  standalone={true}
                />
              </Card>
            </div>
          )}

          {mode === 'non-standalone' && (
            <Card className="p-6">
              <h3 className="text-lg font-semibold mb-4">Non-Standalone Form</h3>
              <p className="text-sm text-muted-foreground mb-4">
                This form has standalone=false, so no header or action buttons
              </p>
              <GearForm
                isEditing={false}
                onSubmit={handleSubmit}
                simplified={false}
                standalone={false}
              />
              <div className="mt-4 pt-4 border-t">
                <p className="text-sm text-muted-foreground">
                  External submit button would go here in real usage
                </p>
              </div>
            </Card>
          )}
        </div>

        {/* Testing Instructions */}
        <Card className="p-4">
          <h3 className="font-medium mb-2">Testing Instructions</h3>
          <ul className="text-sm text-muted-foreground space-y-1">
            <li>• Test responsive behavior by resizing the window</li>
            <li>• Verify field layout matches requirements (Name/Weight first, Category/Options together)</li>
            <li>• Check that weight conversions appear to the right of the weight label</li>
            <li>• Test advanced options toggle (except in simplified mode)</li>
            <li>• Verify image upload is in advanced section</li>
            <li>• Test form validation by submitting with empty/invalid data</li>
            <li>• Check smart category suggestions (try typing "tent", "jacket", etc.)</li>
          </ul>
        </Card>
      </div>
    </div>
  )
}

