import { MobileFormDrawer } from '@/components/ui/mobile-form-drawer'
import type { GearItem, GearCategory } from '@/types/database'
import { GearForm } from './GearForm'

interface GearFormData {
  name: string
  brand: string | null
  model: string | null
  category: GearCategory
  weight_grams: number
  quantity: number
  worn: boolean
  consumable: boolean
  notes: string | null
  price: number | null
  description: string | null
  image_url: string | null
}

interface EditGearFormProps {
  item: GearItem
  onUpdate: (id: string, updates: Partial<Omit<GearItem, 'id' | 'user_id' | 'created_at' | 'updated_at'>>) => void
  onCancel: () => void
}

export function EditGearForm({ item, onUpdate, onCancel }: EditGearFormProps) {
  const handleSubmit = async (data: any) => {
    await onUpdate(item.id, data)
  }

  const initialData = {
    name: item.name,
    brand: item.brand,
    model: item.model,
    category: item.category,
    weight_grams: item.weight_grams,
    quantity: item.quantity,
    worn: item.worn,
    consumable: item.consumable,
    price: item.price,
    notes: item.notes,
    description: item.description,
    image_url: item.image_url,
  }

  return (
    <MobileFormDrawer
      isOpen={true}
      onClose={onCancel}
      title="Edit Gear Item"
      primaryAction={{
        label: 'Update Item',
        onClick: () => {
          const form = document.querySelector('form[data-gear-form]') as HTMLFormElement
          if (form) {
            form.requestSubmit()
          }
        },
        loading: false
      }}
      secondaryAction={{
        label: 'Cancel',
        onClick: onCancel
      }}
    >
      <div className="p-6">
        <GearForm
          isEditing={true}
          initialData={initialData}
          onSubmit={handleSubmit}
          standalone={false}
        />
      </div>
    </MobileFormDrawer>
  )
}

