import { describe, it, expect, vi } from 'vitest'
import { render, screen } from '@testing-library/react'
import { GearForm } from './GearForm'
import React from 'react'

// Mock the auth context
vi.mock('@/contexts/AuthContext', () => ({
  useAuth: () => ({
    user: { id: 'test-user-id', email: 'test@example.com' },
    loading: false,
    signIn: vi.fn(),
    signUp: vi.fn(),
    signOut: vi.fn()
  }),
  AuthProvider: ({ children }: { children: React.ReactNode }) => <>{children}</>
}))

// Mock the image upload module
vi.mock('@/lib/imageUpload', () => ({
  uploadGearImage: vi.fn(),
  deleteGearImage: vi.fn()
}))

// Test wrapper for components
const TestWrapper = ({ children }: { children: React.ReactNode }) => {
  return <div>{children}</div>
}

describe('GearForm', () => {
  const mockOnSubmit = vi.fn()

  beforeEach(() => {
    vi.clearAllMocks()
  })

  describe('Edit Mode Weight Initialization', () => {
    it('should initialize weight unit to grams when editing with weight_grams', () => {
      const initialData = {
        name: 'Test Item',
        weight_grams: 100,
        category: 'Other' as const
      }

      render(
        <TestWrapper>
          <GearForm 
            isEditing={true}
            initialData={initialData}
            onSubmit={mockOnSubmit}
          />
        </TestWrapper>
      )

      // Check that weight value shows the grams value
      const weightInput = screen.getByDisplayValue('100')
      expect(weightInput).toBeInTheDocument()

      // Check that the weight unit selector shows 'g' (grams)
      // The SimpleSelect should have 'g' as the current selection
      const gramButton = screen.getByRole('button', { name: /g/i })
      expect(gramButton).toBeInTheDocument()
    })

    it('should initialize weight unit to oz when adding new item (no weight_grams)', () => {
      render(
        <TestWrapper>
          <GearForm 
            isEditing={false}
            onSubmit={mockOnSubmit}
          />
        </TestWrapper>
      )

      // Check that the weight unit selector shows 'oz' by default for new items
      const ozButton = screen.getByRole('button', { name: /oz/i })
      expect(ozButton).toBeInTheDocument()
    })
  })
})

