input.new_string:
import { test, expect } from '@playwright/test'

test('simple homepage test', async ({ page }) => {
  // Navigate to the home page  
  await page.goto('/')
  await page.waitForLoadState('networkidle')

  // Log what we see
  console.log('Current URL:', page.url())
  console.log('Page title:', await page.title())

  // Take a screenshot to debug
  await page.screenshot({ path: 'debug-homepage.png' })

  // Check if we can see any text on the page
  const bodyText = await page.locator('body').textContent()
  console.log('Body text preview:', bodyText?.substring(0, 200))

  // Try to navigate directly to login
  await page.goto('/login')
  await page.waitForLoadState('networkidle')

  console.log('Login URL:', page.url())
  await page.screenshot({ path: 'debug-login.png' })

  // Check if email field exists
  const emailField = page.locator('#email')
  const emailExists = await emailField.isVisible().catch(() => false)
  console.log('Email field visible:', emailExists)
})

